import os
import json
import base64
from openai import OpenAI

def extract_receipt_info(image_bytes: bytes) -> dict:
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
    base64_image = base64.b64encode(image_bytes).decode()
    response = client.chat.completions.create(
        model="gpt-4o",
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": """Extract structured data from this receipt image as JSON.

Required fields:
- merchant: string (store or merchant name)
- tax: float or null (total tax amount)
- total: float or null (grand total)
- items: array of objects, each with:
  - name: string (item description)
  - quantity: number (quantity)
  - price: number (unit price)

Use null for missing values. Match schema exactly.""",
                    },
                    {
                        "type": "image_url",
                        "image_url": {"url": f"data:image/jpeg;base64,{base64_image}"},
                    },
                ],
            }
        ],
        response_format={"type": "json_object"},
    )
    content = response.choices[0].message.content
    data = json.loads(content)
    # Normalize items to ensure list of dicts
    if not isinstance(data.get("items"), list):
        data["items"] = []
    return {
        "merchant": data.get("merchant", ""),
        "tax": float(data.get("tax", 0.0)) if data.get("tax") is not None else None,
        "total": float(data.get("total", 0.0)) if data.get("total") is not None else None,
        "items": [
            {
                "name": item.get("name", ""),
                "quantity": float(item.get("quantity", 1.0)) if item.get("quantity") is not None else 1.0,
                "price": float(item.get("price", 0.0)) if item.get("price") is not None else 0.0,
            }
            for item in data.get("items", [])
        ],
    }
